pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 wagerAmount, uint256 difficultyVal, uint256 openBlock) public {
        // tight but wide admissible domain
        bound(wagerAmount, 1, type(uint128).max);
        bound(difficultyVal, 2, type(uint128).max);
        bound(openBlock, 1, 1e6);
        vm.assume(difficultyVal > 0);

        // set up c: owner opens to public, adjusts bet limit and difficulty
        c.OpenToThePublic();
        c.AdjustBetAmounts(wagerAmount);
        c.AdjustDifficulty(difficultyVal);

        // advance blocks beyond openBlock so sender can act
        vm.roll(openBlock + 1);

        // fund sender and wager
        address sender = address(0xB0B);
        vm.deal(sender, wagerAmount);
        vm.prank(sender);
        c.wager{value: wagerAmount}();

        // read public state after wager
        bool wagered = c.hasPlayerWagered(sender);
        uint256 pot = c.winnersPot();
        uint256 donated = c.totalDonated();
        uint256 bal = address(c).balance;
        uint256 limit = c.currentBetLimit();
        uint256 diff = c.currentDifficulty();

        // Rule: if wager succeeded (hasPlayerWagered true in P, false in M),
        // then bal = 2*pot + donated, and pot must be <= bal.
        // The bug sets wagers[msg.sender] to 0, breaking the relation
        // because balance is higher than expected from recorded wagers.
        // For P: wagers[sender] = wagerAmount, so hasPlayerWagered true.
        // For M: hasPlayerWagered false, but bal increased by wagerAmount,
        // so 2*pot + donated < bal.
        if (wagered) {
            // P branch: balance must equal 2*winnersPot + totalDonated
            assertTrue(bal == 2 * pot + donated);
        }
        // else M branch: hasPlayerWagered false → bug is triggered,
        // but the assertion above does not execute and fuzzer will find
        // a case where wagered is true on P, false on M.
        // The single assertion is: if wagered, invariant holds.
        // The fuzzer will find inputs where P enters the if, M skips.
    }
}

