pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 wagerAmount, uint256 difficulty) public {
        // 1. restrict to admissible domain
        vm.assume(wagerAmount > 0);
        vm.assume(difficulty >= 2);
        address player = address(0x123);
        vm.deal(player, wagerAmount);

        // 2. setup contract state
        vm.prank(address(this));
        c.AdjustDifficulty(difficulty);
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(wagerAmount);

        // 3. player wagers
        vm.prank(player);
        c.wager{value: wagerAmount}();

        // 4. advance block so play is possible
        vm.roll(block.number + 1);

        // 5. record balance before play
        uint256 balanceBefore = address(c).balance;

        // 6. try to play; if it reverts, ok = false
        bool ok;
        vm.prank(player);
        try c.play() {
            ok = true;
        } catch {
            ok = false;
        }

        // 7. if play succeeded, check balance decreased by wagerAmount/2 (loss)
        if (ok) {
            uint256 balanceAfter = address(c).balance;
            uint256 expectedLoss = wagerAmount / 2;
            assertTrue(balanceBefore - balanceAfter == expectedLoss);
        } else {
            // If it reverted, that's also fine for reference (but bug makes it always revert, so we need to handle)
            // The property: play must either revert or cause a loss of wagerAmount/2.
            // For reference, play does NOT revert, so balance change always occurs.
            // The bug causes play to revert (wagers[player]==0), so ok will always be false for bug,
            // which violates the expected behavior. We'll encode: if ok is false, test fails.
            // But the property must hold for ALL inputs on reference. For reference, play never reverts
            // if wager succeeded and block advanced, so we can assert ok.
            assertTrue(ok);
        }
    }
}

