        vm.assume(player != address(0));
        vm.assume(player != address(c));
        vm.assume(player != address(this));

        // Setup: open contract to public and set bet limit
        c.AdjustBetAmounts(betLimit);
        c.OpenToThePublic();

        // Record the sum of winnersPot() + totalDonated() before wager
        uint256 potBefore = c.winnersPot();
        uint256 donatedBefore = c.totalDonated();
        uint256 sumBefore = potBefore + donatedBefore;

        // player wagers with betLimit ether
        vm.deal(player, betLimit);
        vm.prank(player);
        c.wager{value: betLimit}();

        // Record the sum after wager
        uint256 potAfter = c.winnersPot();
        uint256 donatedAfter = c.totalDonated();
        uint256 sumAfter = potAfter + donatedAfter;

        // The increase should equal the betLimit, reflecting the recorded wager.
        // Reference: the wager is recorded → ethBalance increases, and since no payout/loss yet,
        // winnersPot increases by betLimit/2 + betLimit/2? Actually ethBalance increases by betLimit.
        // winnersPot() = ethBalance / 2, so it increases by betLimit/2.
        // totalDonated unchanged (donations happen in loseWager/donateToWhale).
        // Therefore sumAfter - sumBefore == betLimit/2.
        // Mutant: wager not recorded → contract balance unchanged → winnersPot unchanged → sum difference 0.
        assertTrue(sumAfter == sumBefore + betLimit / 2);
    }
}

